import {assertCustomerDemoRuntimeClosed} from '../../src/customer-demo-runtime.js';
export async function verifyNativeSalesAndCompanyRoles({db,profile,revision,secret}){
 const keys=['JWT_SECRET','MWS_STORE_LIFECYCLE_PROFILE','RENDER_GIT_COMMIT','BACKUP_MONITOR_SECRET'],saved=Object.fromEntries(keys.map(k=>[k,process.env[k]]));Object.assign(process.env,{JWT_SECRET:'isolated-native-extra-sales-secret',MWS_STORE_LIFECYCLE_PROFILE:`BACKOFFICE_COMPANY_${profile}_V1`,RENDER_GIT_COMMIT:revision,BACKUP_MONITOR_SECRET:secret});
 const mutate=(sql,...values)=>db.$transaction(async tx=>{await tx.$queryRawUnsafe("SELECT set_config('mws.lifecycle_generations',$1,true)",JSON.stringify({selected:'7',sibling:'0',foreign:'0'}));return tx.$executeRawUnsafe(sql,...values)});
 let server;
 try{
  for(const module of ['SALES_ANALYTICS','STORE_MODE'])await mutate('INSERT INTO "CompanyModule"("id","companyId","moduleKey","active") VALUES($1,\'company\',$2,true) ON CONFLICT("companyId","moduleKey") DO UPDATE SET "active"=true','native-sales-'+module,module);
  await mutate('UPDATE "StorePaidModule" SET "active"=true WHERE "id"=\'native-PERSONNEL_BASIC\'');
  await mutate('UPDATE "BackofficeStaffGrant" SET "capabilities"=$1::jsonb WHERE "userId"=\'staff\' AND "storeId"=\'selected\'',JSON.stringify(['unsold-products.read','sales-journal.read']));
  for(const id of ['unsold','sold'])await mutate('INSERT INTO "Product"("id","companyId","name","sku") VALUES($1,\'company\',$2,$3)','native-sales-'+id,'Native '+id,'NATIVE_'+id);
  for(const [id,store,product]of [['unsold','selected','native-sales-unsold'],['sold','selected','native-sales-sold'],['foreign-product','selected','foreign-item']])await mutate('INSERT INTO "StoreProduct"("id","storeId","productId") VALUES($1,$2,$3)','native-sales-stock-'+id,store,product);
  for(const [id,company,store]of [['foreign','foreign','foreign'],['sibling','company','sibling'],['selected','company','selected']])await mutate('INSERT INTO "Sale"("id","companyId","storeId","occurredAt","total","subtotal","originalSaleId","customerId","clientTransactionId","saleFingerprint") VALUES($1,$2,$3,\'2026-11-18T10:00:00\',10,10,$4,$5,\'PII_SALES_CANARY\',\'PII_SALES_CANARY\')','native-sale-'+id,company,store,id==='selected'?'native-sale-foreign':null,id==='selected'?'Customer-foreign':null);
  for(const [id,sale,product]of [['sold','selected','native-sales-sold'],['sibling','sibling','native-sales-unsold'],['foreign-product','selected','foreign-item']])await mutate('INSERT INTO "SaleLine"("id","saleId","productId","description","quantity","unitPrice","lineTotal","scannedBarcode") VALUES($1,$2,$3,\'Displayed native line\',1,10,10,\'PII_SALES_CANARY\')','native-line-'+id,'native-sale-'+sale,product);
  await mutate('INSERT INTO "Payment"("id","saleId","method","amount","terminalRef") VALUES(\'native-sales-payment\',\'native-sale-selected\',\'CASH\',10,\'PII_SALES_CANARY\')');
  await mutate('INSERT INTO "WorkforceEmployeeRole"("id","employeeId","roleId") VALUES(\'native-foreign-role-reference\',\'wf-employee-foreign\',\'wf-role-visible\')');
  await mutate('INSERT INTO "WorkforceShiftTemplate"("id","companyId","storeId","name","code","startTime","endTime","requiredRoleId") VALUES(\'native-foreign-template-reference\',\'foreign\',\'foreign\',\'Foreign excluded\',\'NATIVE_CROSS\',\'07:00\',\'15:00\',\'wf-role-visible\')');
  for(const [store,company]of [['sibling','company'],['foreign','foreign']])await mutate('INSERT INTO "StorePaidModule"("id","companyId","storeId","moduleKey","active") VALUES($1,$2,$3,\'PERSONNEL_BASIC\',true)','native-extra-basic-'+store,company,store);
  await mutate('UPDATE "StorePaidModule" SET "active"=false WHERE "id"=\'native-PERSONNEL_BASIC\'');
  await mutate('UPDATE "CompanyModule" SET "active"=false WHERE "companyId"=\'company\' AND "moduleKey"=\'CORE\'');
  const owner={id:'company-owner',companyId:'company',role:'OWNER',tokenType:'BACKOFFICE_USER',sessionId:'company-owner-session',sessionVersion:0};
  const created=await createStaffAccount(db,owner,{username:'company.roles.native',fullName:'Company Roles Native',pin:'987654',grants:[],companyCapabilities:['workforce-role-registry.read']});
  assert.equal((await db.$queryRawUnsafe('SELECT 1 FROM "BackofficeStaffGrant" WHERE "userId"=$1',created.id)).length,0);
  await mutate('INSERT INTO "UserSession"("id","userId","expiresAt") VALUES(\'native-role-company-session\',$1,NOW()+INTERVAL \'1 hour\')',created.id);
  let afterRead=null;const readDb=new Proxy(db,{get(target,key){if(['$executeRaw','$executeRawUnsafe','$transaction'].includes(key))return()=>assert.fail('native report attempted mutation/bootstrap');const value=target[key];if(key==='$queryRaw')return async(...args)=>{const rows=await value.apply(target,args);if(afterRead&&/FROM "(?:StoreProduct|Sale|WorkforceRole)"/.test(args[0].join('?'))){const action=afterRead;afterRead=null;await action()}return rows};return typeof value==='function'?value.bind(target):value}});
  const authSource=await readFile(new URL('../../src/middleware/auth.js',import.meta.url),'utf8'),auth=new Function('prisma','jwt','assertCustomerDemoRuntimeClosed','enforceBackofficeStaff',authSource.slice(authSource.indexOf('export async function auth(')).replace('export async function auth','async function auth')+';return auth;')(readDb,jwt,assertCustomerDemoRuntimeClosed,enforceBackofficeStaff);
  const app=express();app.use(express.json());const index=await readFile(new URL('../../src/index.js',import.meta.url),'utf8'),start=index.indexOf('// Exact delegated sales reports'),end=index.indexOf('// Exact delegated workforce settings',start);assert.ok(start>0&&end>start);new Function('app','auth','readStaffSalesExtra','prisma',index.slice(start,end))(app,auth,readStaffSalesExtra,readDb);
  app.get('/api/backoffice-staff/company/workforce-roles',auth,async(req,res,next)=>{try{res.json(await readStaffCompanyDirectory(readDb,req))}catch(e){next(e)}});app.use((_req,res)=>res.status(404).json({code:'UNEXPECTED_FALLTHROUGH'}));app.use((e,_req,res,_next)=>res.status(e.status||500).json({code:e.code}));server=app.listen(0,'127.0.0.1');await new Promise(resolve=>server.once('listening',resolve));
  const claims={companyId:'company',role:'EMPLOYEE',tokenType:'BACKOFFICE_USER',staffAccess:true,sessionVersion:0},staffToken=jwt.sign({...claims,id:'staff',sessionId:'workforce-native-session'},process.env.JWT_SECRET),companyUser={...claims,id:created.id,sessionId:'native-role-company-session'},companyToken=jwt.sign(companyUser,process.env.JWT_SECRET);
  const get=async(path,{company=false,headers={}}={})=>{const r=await fetch(`http://127.0.0.1:${server.address().port}${path}`,{headers:{authorization:'Bearer '+(company?companyToken:staffToken),[company?'x-backoffice-company-id':'x-backoffice-store-id']:company?'company':'selected',...headers}});return {status:r.status,body:await r.json()}};
  const unsold='/api/commerce/sales/unsold-products?storeId=selected&from=2026-11-18&to=2026-11-18',journal='/api/store-pos/sales/journal?storeId=selected&from=2026-11-18T00%3A00%3A00Z&to=2026-11-19T00%3A00%3A00Z',registry='/api/backoffice-staff/company/workforce-roles';
  const u=await get(unsold);assert.equal(u.status,200,JSON.stringify(u));assert.equal(u.body.complete,true);assert.ok(u.body.products.some(p=>p.id==='native-sales-unsold'));assert.ok(!u.body.products.some(p=>['native-sales-sold','foreign-item'].includes(p.id)));
  const j=await get(journal);assert.equal(j.status,200,JSON.stringify(j));assert.deepEqual(j.body.rows.map(r=>r.id),['native-sale-selected']);const row=j.body.rows[0];assert.equal(row.customerName,null);assert.equal(row.originalSaleId,null);assert.equal(row.originalSaleUnavailable,true);assert.equal(row.lines.find(l=>l.id==='native-line-foreign-product').productUnavailable,true);assert.equal(row.lines.find(l=>l.id==='native-line-foreign-product').productId,null);assert.doesNotMatch(JSON.stringify(j.body),/PII_SALES_CANARY/);assert.equal(row.payments[0].amount,10);
  const r=await get(registry,{company:true});assert.equal(r.status,200,JSON.stringify(r));assert.equal(r.body.scope,'COMPANY');assert.equal(r.body.count,3);assert.ok(r.body.items.some(r=>r.id==='wf-role-unreferenced'));assert.ok(!r.body.items.some(r=>r.id==='wf-role-foreign'));assert.equal(r.body.items.find(r=>r.id==='wf-role-visible').shiftTemplateCount,2);assert.equal(r.body.items.find(r=>r.id==='wf-role-visible').employeeCount,2);assert.equal(r.body.items.find(r=>r.id==='wf-role-hidden').employeeCount,1);
  for(const path of [unsold.replace('storeId=selected','storeId=sibling'),unsold+'&q=foreign',journal.replace('00%3A00%3A00Z','00%3A00'),registry+'?storeId=selected'])assert.ok([400,403].includes((await get(path,{company:path.startsWith(registry)})).status));assert.equal((await get(registry,{company:true,headers:{'x-backoffice-store-id':'selected'}})).status,403);
  await mutate('UPDATE "StorePaidModule" SET "active"=false WHERE "companyId"=\'company\'');await assert.rejects(requireStaffCompanyGrant(readDb,companyUser,'workforce-role-registry.read'),{code:'MODULE_DISABLED'});await mutate('UPDATE "StorePaidModule" SET "active"=true WHERE "id"=\'native-PERSONNEL_BASIC\'');
  for(const [module,path]of [['SALES_ANALYTICS',unsold],['STORE_MODE',journal]]){await mutate('UPDATE "CompanyModule" SET "active"=false WHERE "companyId"=\'company\' AND "moduleKey"=$1',module);assert.equal((await get(path)).status,403);await mutate('UPDATE "CompanyModule" SET "active"=true WHERE "companyId"=\'company\' AND "moduleKey"=$1',module)}
  afterRead=()=>mutate('UPDATE "BackofficeStaffGrant" SET "revision"="revision"+1 WHERE "userId"=\'staff\'');assert.equal((await get(unsold)).status,403);afterRead=()=>mutate('UPDATE "BackofficeStaffAccount" SET "revision"="revision"+1 WHERE "userId"=$1',created.id);assert.equal((await get(registry,{company:true})).status,403);
 }finally{if(server){server.closeAllConnections();await new Promise(resolve=>server.close(resolve))}for(const key of keys){if(saved[key]===undefined)delete process.env[key];else process.env[key]=saved[key]}}
}
